INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"11e1213f-9704-59c1-8f64-9fbbb7893eff","title":"Life Orientation · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 10","questions":[{"question":"A learner balances schoolwork, family duties and sport. What is a useful first step when demands clash?","options":["List priorities, discuss constraints and agree a workable schedule","Assume every demand can happen at the same time","Stop communicating with everyone","Give up every long-term goal immediately"],"correct_index":0,"explanation":"Life roles can compete for time. Planning and respectful discussion help negotiate realistic responsibilities and support.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A friend pressures a learner to ignore an agreed boundary. Which response is healthiest?","options":["Agree because friendship removes choice","Threaten retaliation","Assume discomfort must always be ignored","State the boundary clearly and seek trusted support if pressure continues"],"correct_index":3,"explanation":"Healthy relationships respect consent and boundaries. Support from a trusted adult or professional can help when pressure or harm persists.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is a respectful response to different religious beliefs at school?","options":["Assume everyone shares one belief","Mock unfamiliar practices","Discuss differences without discrimination and respect others' rights","Exclude people from learning because of belief"],"correct_index":2,"explanation":"A diverse society needs respectful participation and protection of rights. Disagreement does not justify discrimination or harassment.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why is match-fixing unethical?","options":["It improves fairness for all participants","It is the same as training harder","It affects only the colour of uniforms","It undermines fair competition and trust in sporting results"],"correct_index":3,"explanation":"Manipulating results for improper advantage harms players, supporters and the integrity of sport.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A training advert promises a recognised qualification but names no awarding body. What should a learner do before paying?","options":["Pay immediately because attractive branding proves recognition.","Assume every online course has identical recognition.","Verify the provider and qualification through credible official channels and compare the terms.","Use only testimonials supplied by the seller."],"correct_index":2,"explanation":"Recognition, provider legitimacy, costs and entry requirements need independent checking. Promotional testimonials and presentation alone cannot establish the status or value of a qualification.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lo"],"metadata":{"term":2,"focus":"Mixed revision: Life roles, relationships and careers; Lifelong learning, diversity and ethical sport","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8f4bf17e-8688-5bd4-9602-798d16aebaf7","title":"Life Orientation · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 10","questions":[{"question":"A class identifies unsafe litter near its school. What is a constructive civic response?","options":["Burn all waste without permission or safety checks","Ignore other people's concerns","Share unverified accusations online","Investigate safely and work with the school and relevant local services on a plan"],"correct_index":3,"explanation":"Civic participation combines evidence, safe action and cooperation. Define the problem, agree responsibilities and evaluate the outcome.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A study plan has five hours without breaks after a full school day. What is a useful improvement?","options":["Remove sleep to fit more work","Avoid all difficult subjects forever","Use manageable focused sessions with breaks and realistic priorities","Treat a missed session as failure of the whole year"],"correct_index":2,"explanation":"A sustainable plan considers attention, rest, tasks and available time. Review and adapt it rather than demanding an unrealistic schedule.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is a respectful response to different religious beliefs at school?","options":["Assume everyone shares one belief","Mock unfamiliar practices","Discuss differences without discrimination and respect others' rights","Exclude people from learning because of belief"],"correct_index":2,"explanation":"A diverse society needs respectful participation and protection of rights. Disagreement does not justify discrimination or harassment.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why is match-fixing unethical?","options":["It improves fairness for all participants","It is the same as training harder","It affects only the colour of uniforms","It undermines fair competition and trust in sporting results"],"correct_index":3,"explanation":"Manipulating results for improper advantage harms players, supporters and the integrity of sport.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A training advert promises a recognised qualification but names no awarding body. What should a learner do before paying?","options":["Pay immediately because attractive branding proves recognition.","Assume every online course has identical recognition.","Verify the provider and qualification through credible official channels and compare the terms.","Use only testimonials supplied by the seller."],"correct_index":2,"explanation":"Recognition, provider legitimacy, costs and entry requirements need independent checking. Promotional testimonials and presentation alone cannot establish the status or value of a qualification.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lo"],"metadata":{"term":3,"focus":"Mixed revision: Civic responsibility and study skills; Lifelong learning, diversity and ethical sport","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"7ffb2ddb-a802-5fde-8a17-7c335f10302d","title":"Life Orientation · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Life Orientation","grade":"Grade 10","questions":[{"question":"A class identifies unsafe litter near its school. What is a constructive civic response?","options":["Burn all waste without permission or safety checks","Ignore other people's concerns","Share unverified accusations online","Investigate safely and work with the school and relevant local services on a plan"],"correct_index":3,"explanation":"Civic participation combines evidence, safe action and cooperation. Define the problem, agree responsibilities and evaluate the outcome.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A study plan has five hours without breaks after a full school day. What is a useful improvement?","options":["Remove sleep to fit more work","Avoid all difficult subjects forever","Use manageable focused sessions with breaks and realistic priorities","Treat a missed session as failure of the whole year"],"correct_index":2,"explanation":"A sustainable plan considers attention, rest, tasks and available time. Review and adapt it rather than demanding an unrealistic schedule.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is assertive communication?","options":["Threatening others until they agree","Expressing needs clearly and respectfully while respecting others' rights","Never expressing any needs","Spreading rumours instead of talking"],"correct_index":1,"explanation":"Assertiveness differs from aggression and passivity. It combines clarity, boundaries and respect.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why research several careers before choosing school-to-work pathways?","options":["Every career has identical requirements","A single advertisement guarantees employment","Entry requirements, tasks and opportunities differ","Personal interests never matter"],"correct_index":2,"explanation":"Compare reliable information about qualifications, costs, daily work and opportunities with interests and strengths. Keep alternatives open.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A learner's career plan conflicts with family duties and transport limits. Which decision process is strongest?","options":["Choose solely by a career title's popularity.","Ignore all constraints because motivation removes them.","Compare pathways and requirements, discuss support and make a feasible schedule with alternatives.","Abandon all goals without investigating options."],"correct_index":2,"explanation":"A sound plan integrates interests with practical requirements and available support. Comparing alternatives and discussing constraints can identify workable routes rather than treating barriers as either irrelevant or final.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lo"],"metadata":{"term":4,"focus":"Mixed revision: Civic responsibility and study skills; Life roles, relationships and careers","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=aovsPAsVZao%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lo-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=ntp5i2bToS4%3d&tabid=3205&portalid=0&mid=10736"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"f9bd7323-08a1-5d02-a818-570a6f716045","title":"English HL · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 10","questions":[{"question":"What is the main purpose of the text?","options":["To report a completed sports match","To persuade people to join a reading circle","To explain how electricity works","To provide a formal exam timetable"],"correct_index":1,"explanation":"The invitation, command and positive promise encourage participation. Purpose concerns what the writer wants the audience to do or think.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which verb begins an imperative in the text?","options":["Join","Ideas","Everyone","Quickly"],"correct_index":0,"explanation":"Join directly urges the reader to act. Imperatives commonly omit the subject you, which is understood.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"What does a blanket of dust suggest?","options":["Someone left a literal wool blanket","The room is outdoors","The sun has disappeared","Dust covers surfaces extensively"],"correct_index":3,"explanation":"The metaphor compares a covering of dust to a blanket. Interpret its effect rather than treating it as a literal object.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which detail shows an act of care?","options":["Lindi waters the plant","The dust covers the room","The classroom is described as sleeping","The window exists"],"correct_index":0,"explanation":"Watering the plant is a deliberate action that supports its life. This provides evidence for character interpretation.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which evaluation best explains the effect of placing Lindi's action after the dust imagery?","options":["The watering proves the classroom has never been used.","The dust establishes that Lindi dislikes all plants.","The small act of watering offers a contrast to the room's apparent neglect.","The sequence proves every other learner is careless."],"correct_index":2,"explanation":"The blanket of dust suggests neglect, while watering sustains a living plant. Their juxtaposition creates a meaningful contrast without establishing everyone's motives.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","enhl"],"metadata":{"term":2,"focus":"Mixed revision: Persuasive language and audience; Literary imagery and revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"a26e57fc-938e-565a-bae8-4ff09c47f55c","title":"English HL · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 10","questions":[{"question":"Where does Mila arrive?","options":["At the library","At a stadium","At a hospital","At the test venue"],"correct_index":0,"explanation":"The first sentence states the location directly. A retrieval question asks for information explicitly present in the text.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which statement is an unsupported addition to the passage?","options":["Mila has a book","The library lights are off","A test is scheduled for tomorrow","Mila failed her test"],"correct_index":3,"explanation":"The passage never gives the test result. An inference must remain within what evidence reasonably supports.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"What does a blanket of dust suggest?","options":["Someone left a literal wool blanket","The room is outdoors","The sun has disappeared","Dust covers surfaces extensively"],"correct_index":3,"explanation":"The metaphor compares a covering of dust to a blanket. Interpret its effect rather than treating it as a literal object.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Which detail shows an act of care?","options":["Lindi waters the plant","The dust covers the room","The classroom is described as sleeping","The window exists"],"correct_index":0,"explanation":"Watering the plant is a deliberate action that supports its life. This provides evidence for character interpretation.","stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which evaluation best explains the effect of placing Lindi's action after the dust imagery?","options":["The watering proves the classroom has never been used.","The dust establishes that Lindi dislikes all plants.","The small act of watering offers a contrast to the room's apparent neglect.","The sequence proves every other learner is careless."],"correct_index":2,"explanation":"The blanket of dust suggests neglect, while watering sustains a living plant. Their juxtaposition creates a meaningful contrast without establishing everyone's motives.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"The classroom slept beneath a blanket of dust. At the window, one small plant leaned towards the sun. Lindi watered it before opening her exercise book."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","enhl"],"metadata":{"term":3,"focus":"Mixed revision: Reading for evidence and inference; Literary imagery and revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"555bd5b2-ae77-5a8e-a8bf-6bd33602b3c5","title":"English HL · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"English HL","grade":"Grade 10","questions":[{"question":"Where does Mila arrive?","options":["At the library","At a stadium","At a hospital","At the test venue"],"correct_index":0,"explanation":"The first sentence states the location directly. A retrieval question asks for information explicitly present in the text.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Which statement is an unsupported addition to the passage?","options":["Mila has a book","The library lights are off","A test is scheduled for tomorrow","Mila failed her test"],"correct_index":3,"explanation":"The passage never gives the test result. An inference must remain within what evidence reasonably supports.","stimulus":"Mila reached the library after the lights had been switched off. She looked at the book in her hand, then at the locked door. Tomorrow's test suddenly felt much closer.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Which expression is a clear exaggeration?","options":["Saturday reading circle","Bring one book","Leave with a hundred ideas","Everyone is welcome"],"correct_index":2,"explanation":"The large promise emphasises benefit rather than giving a measured count. This hyperbole adds persuasive energy.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"What is the effect of whether you read quickly or take your time?","options":["It excludes slower readers","It gives an exact reading-speed statistic","It changes Saturday into a school day","It reassures readers with different reading speeds"],"correct_index":3,"explanation":"The inclusive wording reduces a possible barrier to joining. Explain the effect with reference to the particular audience.","stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Is a hundred ideas best read as a precise promise? Choose the strongest evaluation.","options":["Yes; every participant is guaranteed exactly one hundred ideas.","No; the phrase proves that no ideas will be shared.","No; the exaggeration enthusiastically promotes the circle rather than measuring an exact outcome.","Yes; a precise attendance count is given."],"correct_index":2,"explanation":"The rounded, extravagant number supports persuasive enthusiasm. The passage provides no counting method or guarantee, so treating it as a literal measured promise overstates the evidence.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Join our Saturday reading circle. Bring one book and leave with a hundred ideas! Everyone is welcome, whether you read quickly or take your time."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","enhl"],"metadata":{"term":4,"focus":"Mixed revision: Reading for evidence and inference; Persuasive language and audience","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=WtjOh8RBcU0%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/enhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Ll2-TaTJBoI%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"2a105496-07d9-5e24-9b5e-71da6840a869","title":"Afrikaans HL · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 10","questions":[{"question":"Wat is die hoofdoel van die teks?","options":["Om 'n sportuitslag te gee","Om 'n eksamenrooster te publiseer","Om mense te oorreed om by die leeskring aan te sluit","Om 'n wetenskaplike proses te beskryf"],"correct_index":2,"explanation":"Die uitnodiging en positiewe belofte moedig deelname aan. Die doel is oorredend.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter werkwoord begin 'n bevelsin in die teks?","options":["Idees","Kom","Almal","Vinnig"],"correct_index":1,"explanation":"Kom spreek die leser direk aan en moedig optrede aan. Die onderwerp jy is geïmpliseer.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat suggereer 'n kombers van stof?","options":["Stof bedek die oppervlaktes","Daar lê 'n letterlike wolkombers","Die klas is in die buitelug","Die son het verdwyn"],"correct_index":0,"explanation":"Die metafoor vergelyk die bedekking van stof met 'n kombers. Lees dit figuurlik.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter handeling toon sorg?","options":["Die stof lê in die kamer","Lindi gee die plant water","Die venster bestaan","Die boek is toe"],"correct_index":1,"explanation":"Water gee ondersteun die plant se lewe en bied konkrete bewys van sorg.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat is die uitwerking van Lindi se handeling ná die stofbeeld?","options":["Dit bewys dat niemand die klaskamer ooit gebruik het nie.","Dit bewys dat Lindi plante haat.","Die klein daad van sorg kontrasteer met die vertrek se oënskynlike verwaarlosing.","Dit toon dat elke ander leerder onverskillig is."],"correct_index":2,"explanation":"Die kombers van stof suggereer verwaarlosing, terwyl water die plant onderhou. Die teenstelling ondersteun 'n tema sonder om almal se motiewe te bewys.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","afhl"],"metadata":{"term":2,"focus":"Mixed revision: Oorreding en teikengehoor; Beeldspraak en karakter","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"07b1926f-a0f3-5822-9825-8f3876c7fb2f","title":"Afrikaans HL · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 10","questions":[{"question":"Waar kom Lina aan?","options":["By die stasie","By die biblioteek","By die hospitaal","By die sportveld"],"correct_index":1,"explanation":"Die eerste sin noem die plek uitdruklik. Gebruik die teks as bewys vir 'n direkte begripsvraag.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Watter stelling word nie deur die teks ondersteun nie?","options":["Lina het die toets gedruip","Die ligte is af","Lina hou 'n boek vas","Die toets is môre"],"correct_index":0,"explanation":"Die uitslag verskyn nie in die teks nie. Moenie 'n moontlike vrees as 'n feit aanbied nie.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Wat suggereer 'n kombers van stof?","options":["Stof bedek die oppervlaktes","Daar lê 'n letterlike wolkombers","Die klas is in die buitelug","Die son het verdwyn"],"correct_index":0,"explanation":"Die metafoor vergelyk die bedekking van stof met 'n kombers. Lees dit figuurlik.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Watter handeling toon sorg?","options":["Die stof lê in die kamer","Lindi gee die plant water","Die venster bestaan","Die boek is toe"],"correct_index":1,"explanation":"Water gee ondersteun die plant se lewe en bied konkrete bewys van sorg.","stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat is die uitwerking van Lindi se handeling ná die stofbeeld?","options":["Dit bewys dat niemand die klaskamer ooit gebruik het nie.","Dit bewys dat Lindi plante haat.","Die klein daad van sorg kontrasteer met die vertrek se oënskynlike verwaarlosing.","Dit toon dat elke ander leerder onverskillig is."],"correct_index":2,"explanation":"Die kombers van stof suggereer verwaarlosing, terwyl water die plant onderhou. Die teenstelling ondersteun 'n tema sonder om almal se motiewe te bewys.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Die klaskamer slaap onder 'n kombers van stof. By die venster leun 'n klein plant na die son. Lindi gee dit water voordat sy haar oefenboek oopmaak."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","afhl"],"metadata":{"term":3,"focus":"Mixed revision: Leesbegrip en afleiding; Beeldspraak en karakter","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"5b3b4205-d1d6-54f5-a367-f4130c52d14e","title":"Afrikaans HL · Grade 10 · Term 4 selection · Set B: Mixed revision","subject":"Afrikaans HL","grade":"Grade 10","questions":[{"question":"Waar kom Lina aan?","options":["By die stasie","By die biblioteek","By die hospitaal","By die sportveld"],"correct_index":1,"explanation":"Die eerste sin noem die plek uitdruklik. Gebruik die teks as bewys vir 'n direkte begripsvraag.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Watter stelling word nie deur die teks ondersteun nie?","options":["Lina het die toets gedruip","Die ligte is af","Lina hou 'n boek vas","Die toets is môre"],"correct_index":0,"explanation":"Die uitslag verskyn nie in die teks nie. Moenie 'n moontlike vrees as 'n feit aanbied nie.","stimulus":"Lina kom by die biblioteek aan toe die ligte reeds af is. Sy kyk na die boek in haar hand en dan na die geslote deur. Môre se toets voel skielik baie naby.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Watter uitdrukking is 'n voorbeeld van oordrywing?","options":["Saterdag","een boek","leeskring","'n honderd idees"],"correct_index":3,"explanation":"Die groot getal beklemtoon die moontlike voordeel; dit is nie 'n gemete waarborg nie.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Wat is die funksie van of jy vinnig lees of jou tyd neem?","options":["Dit stel lesers met verskillende leestempo's gerus","Dit sluit stadige lesers uit","Dit gee 'n statistiek","Dit verander die byeenkoms se datum"],"correct_index":0,"explanation":"Die inklusiewe formulering verlaag 'n moontlike hindernis tot deelname.","stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem.","cognitive_level":{"code":"L5","label":"Appreciation","band":"higher"}},{"question":"Is 'n honderd idees hier 'n presiese waarborg? Kies die beste beoordeling.","options":["Ja; elke deelnemer kry presies honderd idees.","Nee; dit bewys dat niemand iets sal leer nie.","Nee; die oordrywing wek entoesiasme eerder as om 'n gemete uitkoms te belowe.","Ja; die teks gee 'n volledige telmetode."],"correct_index":2,"explanation":"Die oordrewe getal maak die uitnodiging aantreklik. Geen telmetode of waarborg word verskaf nie, dus moet die oorredende uitdrukking nie as 'n presiese meting gelees word nie.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Kom Saterdag na ons leeskring! Bring een boek en neem 'n honderd idees huis toe. Almal is welkom, of jy vinnig lees of jou tyd neem."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","afhl"],"metadata":{"term":4,"focus":"Mixed revision: Leesbegrip en afleiding; Oorreding en teikengehoor","language":"af","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=mMkdIZmk3Ow%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/afhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=LnUfxzL2B4A%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"bf1760a9-36c4-5f28-b393-efdfbd3eb22d","title":"isiXhosa HL · Grade 10 · Term 2 selection · Set B: Mixed revision","subject":"isiXhosa HL","grade":"Grade 10","questions":[{"question":"Yintoni eyona njongo yale ntengiso?","options":["Kukuchaza indlela yokulungisa imoto.","Kukubala iindleko zepetroli.","Kukubalisa ngohambo oludlulileyo.","Kukukhuthaza abantu ukuba bajoyine iklabhu."],"correct_index":3,"explanation":"Isimemo kunye nomyalelo othi Joyina namhlanje zizixhobo zokukhuthaza umfundi ukuba enze into.","stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Ngowuphi umbuzo oluncedo ngaphambi kokujoyina?","options":["Ingaba zonke iincwadi zinombala omnye?","Ingaba intengiso iprintwe ngeyiphi inki?","Iphi indawo yentlanganiso kwaye iqala nini?","Ingaba onke amalungu anamagama afanayo?"],"correct_index":2,"explanation":"Indawo nexesha zizinto ezifunekayo ukuze umntu akwazi ukuya. Ulwazi aluchazwanga ngokupheleleyo kwintengiso.","stimulus":"Intengiso ithi: Wamkelekile kwiklabhu yokufunda! Joyina namhlanje. Sabelana ngeencwadi simahla ngoLwesithathu. Le yeyona klabhu ibalaseleyo elizweni!","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Yintoni esinokuyicingela ngokuthula nokubamba ileta?","options":["UNoma ngokuqinisekileyo uphumelele ibhaso.","UNoma usenokuba uxhalabile okanye ulindele okuthile.","UNoma uyayazi yonke into ezayo.","UNoma sele eyifundile ileta."],"correct_index":1,"explanation":"Ukuthula nokungayivuli ileta kunika umkhondo wexhala. Akuchazi ngokuqinisekileyo umxholo weleta.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Leliphi ibango elichazwe ngokucacileyo?","options":["Ileta imxelela ukuba aphumelele.","Imvula iza kuphela ngomzuzu.","UNoma akakayivuli ileta.","UNoma ulinde udade wabo."],"correct_index":2,"explanation":"Amagama athi ileta engayivulanga abungqina obuthe ngqo. Amanye amabango ongeza ulwazi olunganikiweyo.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Uthelekiso lwentliziyo negubu lunegalelo lini kumoya wesicatshulwa?","options":["Lungqina ukuba kukho igubu lokwenene egumbini.","Lusixelela amanqaku akhe esikolo.","Lwenza iimvakalelo zivakale zinamandla, kodwa alusivezeli umxholo wencwadi.","Lungqina ukuba incwadi sele ivuliwe."],"correct_index":2,"explanation":"Uthelekiso lugxininisa ukubetha kwentliziyo nemvakalelo yexesha. Isiphumo solwimi siyavakala, kodwa iinkcukacha zencwadi azikachazwa.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"},"stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu."}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","xhhl"],"metadata":{"term":2,"focus":"Mixed revision: Intengiso, injongo nabaphulaphuli; Imifanekiso-ngqondweni nomlinganiswa","language":"xh","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Iw2OEg6LMVY%3d&tabid=3205&portalid=0&mid=10735","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QsGQeCZMUxo%3d&tabid=570&portalid=0&mid=1555","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/xhhl-10","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS language response: Barrett-informed comprehension and literary analysis","cognitive_levels":["Literal","Reorganisation","Inference","Evaluation","Appreciation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Iw2OEg6LMVY%3d&tabid=3205&portalid=0&mid=10735"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"fcf5043d-b7ed-5ccc-9673-f16e27617192","title":"isiXhosa HL · Grade 10 · Term 3 selection · Set B: Mixed revision","subject":"isiXhosa HL","grade":"Grade 10","questions":[{"question":"Kutheni uLutho esiya kwithala leencwadi?","options":["Ufuna ukuthengisa iincwadi.","Uya kudlala nabantakwabo.","Ufuna indawo ezolileyo yokufunda.","Usebenza apho ebusuku."],"correct_index":2,"explanation":"Isizathu sicaciswe kumazwi kaLutho: ufuna ukufunda kwindawo ezolileyo. Sebenzisa ubungqina obukwisicatshulwa.","stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Leliphi ibango elingenabungqina kwisicatshulwa?","options":["ULutho uboleka incwadi enye.","ULutho ngoyena mfundi uphumelelayo esikolweni.","ULutho ufuna ukuzola.","ULutho ubuyisa incwadi ngoLwesihlanu."],"correct_index":1,"explanation":"Akukho manqaku okanye uthelekiso lwabafundi lunikiweyo. Musa ukongeza ingxelo engaxhaswanga sisicatshulwa.","stimulus":"ULutho ufika kwithala leencwadi emva kwesikolo. Uthi: Ndifuna indawo ezolileyo yokufunda kuba abantakwethu badlala ekhaya. Uphuma nencwadi enye aze abuye nayo ngoLwesihlanu.","cognitive_level":{"code":"L4","label":"Evaluation","band":"higher"}},{"question":"Yintoni esinokuyicingela ngokuthula nokubamba ileta?","options":["UNoma ngokuqinisekileyo uphumelele ibhaso.","UNoma usenokuba uxhalabile okanye ulindele okuthile.","UNoma uyayazi yonke into ezayo.","UNoma sele eyifundile ileta."],"correct_index":1,"explanation":"Ukuthula nokungayivuli ileta kunika umkhondo wexhala. Akuchazi ngokuqinisekileyo umxholo weleta.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L3","label":"Inference","band":"middle"}},{"question":"Leliphi ibango elichazwe ngokucacileyo?","options":["Ileta imxelela ukuba aphumelele.","Imvula iza kuphela ngomzuzu.","UNoma akakayivuli ileta.","UNoma ulinde udade wabo."],"correct_index":2,"explanation":"Amagama athi ileta engayivulanga abungqina obuthe ngqo. Amanye amabango ongeza ulwazi olunganikiweyo.","stimulus":"Imvula ibetha ifestile. UNoma ubambe ileta engayivulanga. Uthe cwaka, ejonga endleleni. Intliziyo yakhe ibetha ngathi ligubu.","cognitive_level":{"code":"L1","label":"Literal","band":"lower"}},{"question":"Uthelekiso lwentliziyo negubu lunegalelo lini kumoya wesicatshulwa?","options":["Lungqina ukuba kukho igubu lokwenene egumbini.","Lusixelela amanqaku akhe esikolo.","Lwenza iimvakalelo zi